create function public.test_command(kind text,serial integer,ago interval,p jsonb) returns jsonb language sql as $$select jsonb_build_object('id','00000000-0000-4000-8000-'||lpad(serial::text,12,'0'),'kind',kind,'occurred_at',date_trunc('minute',now())-ago,'payload',case when p->'gps'->>'captured_at'='PLACEHOLDER' then jsonb_set(p,'{gps,captured_at}',to_jsonb(date_trunc('minute',now())-ago)) else p end)$$;
select public.apply_field_command('00000000-0000-4000-8000-000000000003',public.test_command('shift',101,'3 hours','{"shift_id":"00000000-0000-4000-8000-000000000020","action":"clock_in"}'));
select public.apply_field_command('00000000-0000-4000-8000-000000000003',public.test_command('shift',102,'2 hours','{"shift_id":"00000000-0000-4000-8000-000000000020","action":"break_start"}'));
select public.apply_field_command('00000000-0000-4000-8000-000000000003',public.test_command('shift',103,'90 minutes','{"shift_id":"00000000-0000-4000-8000-000000000020","action":"break_end"}'));
select public.apply_field_command('00000000-0000-4000-8000-000000000003',public.test_command('shift',104,'1 hour','{"shift_id":"00000000-0000-4000-8000-000000000020","action":"clock_out"}'));
select public.apply_field_command('00000000-0000-4000-8000-000000000003',public.test_command('shift',104,'1 hour','{"shift_id":"00000000-0000-4000-8000-000000000020","action":"clock_out"}'));
select public.test_assert((select count(*)=4 from public.shift_events),'retries do not duplicate shift events');
set role service_role;
