do $$begin
 begin perform public.apply_field_command('00000000-0000-4000-8000-000000000003',public.test_command('location',111,'110 minutes','{"shift_id":"00000000-0000-4000-8000-000000000020","latitude":39.17,"longitude":-78.17,"accuracy":5}'));raise exception 'TEST FAILED: break location accepted';exception when others then if sqlerrm not like '%outside active field time%' then raise;end if;end;
 begin perform public.apply_field_command('00000000-0000-4000-8000-000000000003',public.test_command('location',112,'30 minutes','{"shift_id":"00000000-0000-4000-8000-000000000020","latitude":39.17,"longitude":-78.17,"accuracy":5}'));raise exception 'TEST FAILED: off-shift location accepted';exception when others then if sqlerrm not like '%outside active field time%' then raise;end if;end;
end$$;
