 begin perform public.apply_field_command('00000000-0000-4000-8000-000000000003',public.test_command('visit',121,'84 minutes','{"shift_id":"00000000-0000-4000-8000-000000000020","outcome":"no_answer","property":{"id":"00000000-0000-4000-8000-000000000030","address":"1 Oak St, Winchester, VA","latitude":39.17,"longitude":-78.17}}'));raise exception 'TEST FAILED: do-not-knock warning bypassed';exception when others then if sqlerrm not like '%do-not-knock warning%' then raise;end if;end;
 begin perform public.apply_field_command('00000000-0000-4000-8000-000000000003',public.test_command('visit',122,'83 minutes','{"shift_id":"00000000-0000-4000-8000-000000000020","outcome":"inspection_requested","property":{"id":"00000000-0000-4000-8000-000000000031","address":"2 Oak St, Winchester, VA","latitude":39.17,"longitude":-78.17},"lead":{"id":"00000000-0000-4000-8000-000000000040","name":"Sam","phone":"","email":""}}'));raise exception 'TEST FAILED: contactless lead accepted';exception when check_violation then null;end;
end$$;
select public.test_assert(not exists(select 1 from public.properties where id='00000000-0000-4000-8000-000000000031'),'invalid lead rolls back the property and visit');
select public.apply_field_command('00000000-0000-4000-8000-000000000003',public.test_command('visit',123,'82 minutes','{"shift_id":"00000000-0000-4000-8000-000000000020","outcome":"inspection_requested","property":{"id":"00000000-0000-4000-8000-000000000031","address":"2 Oak St, Winchester, VA","latitude":39.17,"longitude":-78.17},"lead":{"id":"00000000-0000-4000-8000-000000000040","name":"Sam","phone":"5405551234","preferred_window":"Tomorrow afternoon"}}'));
