select public.apply_field_command('00000000-0000-4000-8000-000000000003',public.test_command('visit',124,'81 minutes','{"shift_id":"00000000-0000-4000-8000-000000000020","outcome":"no_answer","property":{"id":"00000000-0000-4000-8000-000000000032","address":"3 Elsewhere St","latitude":39.2,"longitude":-78.2},"gps":{"latitude":39.17,"longitude":-78.17,"accuracy":10,"captured_at":"PLACEHOLDER"}}'));
